def choose_move(observation):
    w=observation['grid_width']
    h=observation['grid_height']
    px,py=observation['self_position']
    ox,oy=observation['opponent_position']
    resources=observation['resources']
    obstacles=observation['obstacles']
    score_self=observation['scores'][0]
    score_opp=observation['scores'][1]
    self_path=observation.get('self_path',[])
    opponent_path=observation.get('opponent_path',[])
    def is_free(x,y):
        if x<0 or y<0 or x>=w or y>=h:
            return False
        if (x,y) in obstacles:
            return False
        return True
    dx,dy=0,0
    # Move towards closest resource if exists
    min_d=9999
    target=None
    for r in resources:
        rx,ry=r
        dist=abs(rx-px)+abs(ry-py)
        if dist<min_d:
            min_d=dist
            target=(rx,ry)
    if target:
        tx,ty=target
        if tx>px and is_free(px+1,py):
            dx=1
            dy=0
        elif tx<px and is_free(px-1,py):
            dx=-1
            dy=0
        elif ty>py and is_free(px,py+1):
            dx=0
            dy=1
        elif ty<py and is_free(px,py-1):
            dx=0
            dy=-1
        else:
            # fallback
            for dd,xx,yy in [( (1,0), px+1, py ), ( (-1,0), px-1, py ), ( (0,1), px, py+1 ), ( (0,-1), px, py-1)]:
                if is_free(xx,yy):
                    dx,dy=dd
                    break
    else:
        # No resources, move randomly or towards opponent to chase
        if oy>py and is_free(px,py+1):
            dx,dy=0,1
        elif oy<py and is_free(px,py-1):
            dx,dy=0,-1
        elif ox>px and is_free(px+1,py):
            dx,dy=1,0
        elif ox<px and is_free(px-1,py):
            dx,dy=-1,0
        else:
            for dd,xx,yy in [( (1,0), px+1, py ), ( (-1,0), px-1, py ), ( (0,1), px, py+1 ), ( (0,-1), px, py-1)]:
                if is_free(xx,yy):
                    dx,dy=dd
                    break
    return [dx,dy]
